-- =============================================================================
-- 526 — LE CAHIER D'EXERCICES DE 1RE (partie 14)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 526 --niveau 1re --fichiers francais.n16b,francais.n17a,francais.n17b,francais.n18a,francais.n18b --suffixe 14 > supabase/contenu/526_exercices_1re_14.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n16b           18 exercices · 6 chapitres
--   francais.n17a           18 exercices · 6 chapitres
--   francais.n17b           18 exercices · 6 chapitres
--   francais.n18a           18 exercices · 6 chapitres
--   francais.n18b           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('0e390e42-664f-5a6d-bc5b-0dba4e5564ea'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dix-huit lettres sous un faux nom","competence":"analyser-document","situation":"Tu fiches *Les Provinciales* pour l’oral. Lis la carte d’identité, puis repère les deux camps de la querelle.","documents":[{"id":"id","type":"fiche","modele":"affiche","entete":"Les Provinciales","sousTitre":"Blaise Pascal","emoji":"✉️","lignes":[{"texte":"Titre d’origine","valeur":"Lettres écrites à un provincial"},{"texte":"Nombre de lettres","valeur":"Dix-huit"},{"texte":"Pseudonyme","valeur":"Louis de Montalte","id":"z1"},{"texte":"Publication","valeur":"Clandestine"}],"pied":"Un modèle de polémique","teinte":"violet"},{"id":"camps","type":"tableau","titre":"Les deux camps","colonnes":["Camp","Qui ?"],"lignes":[["Les défendus","Antoine Arnauld et les jansénistes de Port-Royal"],["Les attaquants","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui donne le pseudonyme sous lequel Pascal publie.","aide":"Pascal ne signe pas de son nom.","type":"zone","document":"id","multiple":false},{"enonce":"Complète la phrase avec la fiche.","aide":"Lis les lignes de la fiche.","type":"trous","segments":["Pascal publie ",0," lettres, de façon ",1," ; l’ensemble s’intitule *Lettres écrites à un ",2,"*."],"banque":["provincial","jésuite","clandestine","officielle","dix-huit","vingt"]},{"enonce":"Qui faut-il écrire dans la case « ? » du tableau ?","aide":"Ils ont fait condamner Arnauld en 1656.","type":"choix","options":[{"id":"a","texte":"Les mathématiciens de Paris"},{"id":"b","texte":"Les jansénistes de Port-Royal"},{"id":"c","texte":"La Sorbonne et les jésuites"},{"id":"d","texte":"Antoine Arnauld et ses amis"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Les lettres paraissent sous le pseudonyme de **Louis de Montalte**."},{"cle":{"type":"trous","trous":[["dix huit","18"],["clandestine"],["provincial"]]},"affichage":"dix-huit · clandestine · provincial","explication":"Il publie **dix-huit** lettres, de façon **clandestine**, sous le titre *Lettres écrites à un **provincial***."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les attaquants sont **la Sorbonne et les jésuites**."}]$ex$::jsonb),
  ('0e390e42-664f-5a6d-bc5b-0dba4e5564ea'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un provincial bien naïf","competence":"analyser-texte","situation":"Lis une scène écrite pour l’exercice, à la manière des premières lettres, puis dis comment Pascal s’y prend pour convaincre.","documents":[{"id":"sc","type":"texte","genre":"theatre","titre":"Une visite chez un casuiste","blocs":[{"didascalie":"Un provincial interroge un père casuiste sur une querelle de théologiens."},{"personnage":"Le provincial","replique":"Mon père, je suis ignorant : pouvez-vous m’expliquer cela ?"},{"personnage":"Le père","replique":"Volontiers ! À condition de bien distinguer les cas, rien n’est jamais défendu."}],"source":"Texte écrit pour l’exercice, à la manière des *Provinciales* de Pascal"},{"id":"lettres","type":"tableau","titre":"Deux temps","colonnes":["Les lettres","Leur méthode"],"lignes":[["Les premières","Elles feignent la naïveté : un provincial demande des explications"],["Les suivantes","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel le provincial se présente pour mieux faire parler son interlocuteur.","aide":"Il joue celui qui ne sait rien.","type":"zone","document":"sc","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Après avoir feint de ne pas comprendre, Pascal attaque.","type":"choix","options":[{"id":"a","texte":"Elles attaquent de front la casuistique jésuite"},{"id":"b","texte":"Elles se contentent de citer la Bible"},{"id":"c","texte":"Elles défendent la casuistique des jésuites"},{"id":"d","texte":"Elles renoncent à l’ironie par prudence"}],"multiple":false},{"enonce":"Quel défaut de la morale casuiste la réplique du père montre-t-elle ?","aide":"Relis la phrase du père : « rien n’est jamais défendu ».","type":"choix","options":[{"id":"a","texte":"Elle ignore les cas concrets et reste abstraite"},{"id":"b","texte":"Elle se contredit sur la querelle de la grâce"},{"id":"c","texte":"Elle interdit des gestes pourtant permis par la loi"},{"id":"d","texte":"À force de distinguer les cas, elle permet de tout justifier"}],"multiple":false},{"enonce":"Relie chaque arme de Pascal à son effet.","aide":"Pense à ce que chaque arme apporte au lecteur.","type":"association","gauche":[{"id":"g0","texte":"L’ironie"},{"id":"g1","texte":"La mise en scène dialoguée"},{"id":"g2","texte":"Les citations exactes des adversaires"},{"id":"g3","texte":"Une langue limpide"}],"droite":[{"id":"d0","texte":"Elles sont retournées contre eux"},{"id":"d1","texte":"Elle désarme"},{"id":"d2","texte":"Elle rend le débat accessible"},{"id":"d3","texte":"Elle rend le raisonnement vivant"}]}]}$ex$::jsonb,
