   $ex${"titre":"Pourquoi revenir à la rime ?","competence":"argumenter","situation":"Deux élèves se disputent : le retour d’Aragon à la rime est-il un recul ? Lis leur échange, complète l’argument, puis choisis ta conclusion de dissertation.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Maëlle","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maëlle","texte":"Aragon revient à la rime : c’est un retour en arrière, il renie le surréalisme."},{"qui":"Hugo","texte":"Pas du tout. Un vers qui rime se retient par cœur, donc il peut circuler en cachette."},{"qui":"Maëlle","texte":"Alors la forme ne serait pas un simple décor ?"},{"qui":"Hugo","texte":"Non : le vers régulier devient une arme pour transmettre et chanter."}]},{"id":"th","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le vers régulier sert la Résistance","?","Les poèmes mis en musique par Ferré, Ferrat et Brassens"],["Aragon invente une forme neuve","La fin d’un vers rime avec le début du suivant","La rime enjambée"]]}],"questions":[{"enonce":"Touche le verbe qui donne la raison pour laquelle la rime aide à résister.","aide":"Hugo dit ce que fait l’élève d’un vers qui rime : il le garde en mémoire.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel argument faut-il écrire dans la case « ? » du tableau ?","aide":"Reprends l’argument de Hugo : à quoi sert un poème qu’on sait par cœur ?","type":"choix","options":[{"id":"a","texte":"Il est plus simple à publier en Suisse qu’en France"},{"id":"b","texte":"Il prolonge fidèlement l’écriture surréaliste"},{"id":"c","texte":"Il évite toute allusion à l’amour ou à la guerre"},{"id":"d","texte":"Il se retient par cœur, se transmet et se chante"}],"multiple":false},{"enonce":"Relie chaque choix d’Aragon à son effet.","aide":"Chaque choix de forme a une conséquence sur la façon dont le poème circule.","type":"association","gauche":[{"id":"g0","texte":"Un recueil adressé à Elsa"},{"id":"g1","texte":"Des vers rimés et réguliers"},{"id":"g2","texte":"La rime enjambée"}],"droite":[{"id":"d0","texte":"Un poème qu’on retient et qu’on chante"},{"id":"d1","texte":"La fin d’un vers rime avec le début du suivant"},{"id":"d2","texte":"L’amour peut parler aussi de la France occupée"}]},{"enonce":"Quelle conclusion de dissertation sur la poésie engagée ce recueil permet-il d’appuyer ?","aide":"Aragon parle de la guerre en parlant d’amour, avec des vers faits pour être retenus.","type":"choix","options":[{"id":"a","texte":"On peut résister sans slogan, par l’amour et la mémoire"},{"id":"b","texte":"Une poésie engagée doit renoncer à toute forme travaillée"},{"id":"c","texte":"Le vers libre est la seule forme possible pour résister"},{"id":"d","texte":"La poésie n’a de valeur que loin des événements du monde"}],"multiple":false}]}$ex$::jsonb,
