  ('23e0d27d-5df4-5f0c-8e50-0c4f0f5307e0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Contre le théâtre, pour la fête","competence":"argumenter","situation":"Un camarade te demande de résumer la thèse de Rousseau. Lis le résumé, puis range ses reproches et sa proposition.","documents":[{"id":"resume","type":"texte","genre":"article","titre":"La thèse en bref","blocs":["D’Alembert propose d’ouvrir un théâtre à Genève. Rousseau, qui prend la parole comme citoyen de cette ville, répond par une longue lettre publique : le théâtre, dit-il, amollit les mœurs. On y pleure sur des malheurs imaginaires, et ces larmes tiennent lieu d’action réelle.","Il attaque aussi *Le Misanthrope* : Molière y fait rire d’Alceste, l’homme vertueux. Enfin, dans la salle obscure, les spectateurs restent passifs et isolés. À la place, Rousseau veut des fêtes publiques en plein air, où le peuple est à la fois acteur et spectateur."],"source":"Résumé rédigé pour l’exercice, d’après la *Lettre à d’Alembert sur les spectacles* (1758)"}],"questions":[{"enonce":"Touche le mot qui dit au nom de quoi Rousseau prend la parole.","aide":"Il est né à Genève et défend les mœurs de sa ville.","type":"zone","document":"resume","multiple":false},{"enonce":"Range chaque idée : reproche de Rousseau au théâtre, ou proposition à la place ?","aide":"Cherche ce que Rousseau veut supprimer, puis ce qu’il veut mettre à la place.","type":"categories","categories":[{"id":"c0","texte":"Reproche au théâtre"},{"id":"c1","texte":"Proposition à la place"}],"items":[{"id":"i0","texte":"Il isole les spectateurs"},{"id":"i1","texte":"Un peuple à la fois acteur et spectateur"},{"id":"i2","texte":"Il amollit les mœurs"},{"id":"i3","texte":"Des fêtes publiques en plein air"},{"id":"i4","texte":"Il rend le vice aimable"}]},{"enonce":"Selon ce résumé, pourquoi les larmes versées au théâtre ne servent-elles à rien ?","aide":"Relis la fin de la première phrase du résumé qui parle des larmes.","type":"choix","options":[{"id":"a","texte":"Elles empêchent les acteurs de bien jouer leur rôle"},{"id":"b","texte":"Elles consolent les spectateurs et les rendent meilleurs"},{"id":"c","texte":"Elles tiennent lieu d’action réelle : on pleure au lieu d’agir"},{"id":"d","texte":"Elles coûtent trop cher à la ville de Genève"}],"multiple":false},{"enonce":"Relie chaque reproche à son détail.","aide":"Chaque reproche s’appuie sur un exemple précis du résumé.","type":"association","gauche":[{"id":"g0","texte":"Il amollit les mœurs"},{"id":"g1","texte":"Il rend le vice aimable"},{"id":"g2","texte":"Il isole les citoyens"}],"droite":[{"id":"d0","texte":"Les larmes sur des malheurs fictifs remplacent l’action"},{"id":"d1","texte":"Salle obscure, spectateurs passifs"},{"id":"d2","texte":"Molière fait rire d’Alceste, l’homme vertueux"}]}]}$ex$::jsonb,
