   $ex${"titre":"Se rassembler, ou s’isoler ?","competence":"argumenter","situation":"Zoé et Ilyès ne comprennent pas la même chose de la *Lettre à d’Alembert*. Lis une phrase célèbre, leur débat, puis le tableau pour trancher.","documents":[{"id":"cit","type":"texte","genre":"source","titre":"Une phrase de la Lettre","blocs":["« On croit s’assembler au spectacle, et c’est là que chacun s’isole. »"],"auteur":"Jean-Jacques Rousseau","source":"Jean-Jacques Rousseau, *Lettre à d’Alembert sur les spectacles* (1758)"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Zoé","emoji":"👩","cote":"gauche"},{"nom":"Ilyès","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"Rousseau déteste les rassemblements : il veut que chacun reste chez soi."},{"qui":"Ilyès","texte":"Non, il veut un autre rassemblement : la fête, où le peuple est à la fois acteur et spectateur."},{"qui":"Zoé","texte":"Et pour faire une fête, il faut un grand décor ?"},{"qui":"Ilyès","texte":"Même pas : un piquet couronné de fleurs au milieu d’une place suffit."}]},{"id":"th","type":"tableau","titre":"Deux arguments","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le théâtre isole ceux qui s’y rassemblent","Dans une salle obscure, les spectateurs sont passifs","?"],["La fête rassemble vraiment","Le peuple y est à la fois acteur et spectateur","Le piquet couronné de fleurs au milieu d’une place"]]}],"questions":[{"enonce":"Touche le mot qui dit ce que devient chacun, au spectacle.","aide":"Le verbe qui s’oppose à « s’assembler ».","type":"zone","document":"cit","multiple":false},{"enonce":"Touche le mot qui dit le rôle du peuple dans la fête, à la différence du théâtre.","aide":"Au théâtre, on regarde ; à la fête, que fait aussi le peuple ?","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle formule de la Lettre faut-il écrire dans la case « ? » du tableau ?","aide":"Cherche, dans le premier document, la phrase qui illustre l’isolement des spectateurs.","type":"choix","options":[{"id":"a","texte":"« chacun s’isole »"},{"id":"b","texte":"« Comment peut-on être Persan ? »"},{"id":"c","texte":"« une fête vraie »"},{"id":"d","texte":"« je suis, je vis, j’existe »"}],"multiple":false},{"enonce":"Qui a raison, Zoé ou Ilyès ?","aide":"Rousseau reproche au théâtre d’isoler : que propose-t-il à la place ?","type":"choix","options":[{"id":"a","texte":"Ilyès : Rousseau veut un théâtre plus grand et mieux éclairé"},{"id":"b","texte":"Zoé : Rousseau préfère que les citoyens restent isolés chez eux"},{"id":"c","texte":"Zoé : Rousseau juge la fête plus dangereuse que le théâtre"},{"id":"d","texte":"Ilyès : Rousseau oppose au théâtre une autre forme de rassemblement"}],"multiple":false}]}$ex$::jsonb,
