  ('67e3134c-74a7-5a07-adf2-de99ca6e6116'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le regard d’une étrangère","competence":"argumenter","situation":"Lis une lettre de Zilia écrite pour l’exercice, compare les deux romans épistolaires du siècle, puis tire ta conclusion de dissertation.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre de Zilia","blocs":["Mon cher Aza,","Ici, les hommes s’enferment dans de petites maisons roulantes qu’ils nomment carrosses, et chacun salue l’autre en se penchant, sans jamais le regarder dans les yeux.","Les femmes passent des heures à parer leur visage ; personne ne songe à leur apprendre à penser. Je cherche encore pourquoi ces usages seraient plus raisonnables que les nôtres."],"source":"Texte écrit pour l’exercice, à la manière de Graffigny"},{"id":"cmp","type":"tableau","titre":"Deux romans par lettres","colonnes":["Critère","Lettres persanes","Lettres d’une Péruvienne"],"lignes":[["Date","1721","1747"],["Regard éloigné de","Deux Persans","?"],["Fin","Roxane, révoltée, s’empoisonne","Zilia choisit l’étude et l’amitié"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qui dit à quoi les femmes occupent leur temps.","aide":"Le regard neuf de Zilia se pose sur le visage des femmes.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le mot par lequel Zilia décrit un carrosse sans le comprendre.","aide":"Elle ne connaît pas le mot « carrosse » : par quoi le remplace-t-elle ?","type":"zone","document":"lettre","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Relis la lettre : qui est Zilia ?","type":"choix","options":[{"id":"a","texte":"Un chevalier français"},{"id":"b","texte":"Une princesse espagnole"},{"id":"c","texte":"Un diplomate persan"},{"id":"d","texte":"Une jeune Inca"}],"multiple":false},{"enonce":"Relie chaque procédé à son effet.","aide":"Pense à ce que ressent le lecteur quand Zilia décrit sans comprendre.","type":"association","gauche":[{"id":"g0","texte":"Un objet décrit sans son nom"},{"id":"g1","texte":"Une narratrice étrangère"},{"id":"g2","texte":"Un visage paré, un esprit négligé"}],"droite":[{"id":"d0","texte":"La satire passe par un regard neuf"},{"id":"d1","texte":"La critique de l’éducation des femmes"},{"id":"d2","texte":"L’usage banal devient une énigme"}]},{"enonce":"Quelle différence le tableau fait-il apparaître entre les fins des deux romans ?","aide":"Compare la dernière ligne du tableau pour chacun des deux romans.","type":"choix","options":[{"id":"a","texte":"Les deux héroïnes épousent le premier prétendant"},{"id":"b","texte":"Zilia, contrairement à Roxane, choisit une vie indépendante"},{"id":"c","texte":"Aucune des deux ne parvient à écrire sa lettre"},{"id":"d","texte":"Les deux héroïnes meurent empoisonnées à la fin"}],"multiple":false}]}$ex$::jsonb,
