   $ex${"titre":"La chèvre qui voulait de l’air","competence":"analyser-texte","situation":"Lis le résumé de « La Chèvre de M. Seguin », puis suis les étapes de la chèvre et retrouve ce que chaque personnage représente.","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Le conte en résumé","blocs":["M. Seguin perdait toutes ses chèvres : elles s’ennuyaient au piquet, s’échappaient vers la montagne et le loup les mangeait.","Blanquette, la dernière, rêve elle aussi de liberté. Elle s’échappe, passe une nuit heureuse sur la montagne, puis se bat contre le loup jusqu’au matin.","Au matin, le loup la mange. Le conte laisse chacun devant une question : préfère-t-on la sécurité ou la liberté ?"],"source":"Résumé rédigé pour l’exercice, d’après « La Chèvre de M. Seguin » (1869)"},{"id":"fil","type":"chaine","titre":"Les étapes de Blanquette","disposition":"ligne","noeuds":[{"id":"z1","texte":"M. Seguin perd ses chèvres"},{"id":"z2","texte":"Blanquette s’échappe"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Le loup la mange"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le mot qui nomme ce que les chèvres de M. Seguin fuient.","aide":"C’est ce qui les retient et les attache, dans la première phrase.","type":"zone","document":"conte","multiple":false},{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Entre sa fuite et sa fin, la chèvre vit une nuit unique.","type":"choix","options":[{"id":"a","texte":"Elle revient au piquet avant la nuit et se rendort"},{"id":"b","texte":"Elle passe une nuit libre et se bat contre le loup"},{"id":"c","texte":"Elle se réfugie chez le poète Gringoire"},{"id":"d","texte":"M. Seguin la retrouve et la ramène à l’étable"}],"multiple":false},{"enonce":"Touche le mot qui dit ce que le conte oppose à la liberté.","aide":"La dernière phrase pose le choix : liberté ou… ?","type":"zone","document":"conte","multiple":false},{"enonce":"Relie chaque personnage à ce qu’il représente.","aide":"Un seul de ces personnages est une chèvre, un autre un meunier.","type":"association","gauche":[{"id":"g0","texte":"Blanquette"},{"id":"g1","texte":"Maître Cornille"},{"id":"g2","texte":"Le berger des « Étoiles »"},{"id":"g3","texte":"Jan"}],"droite":[{"id":"d0","texte":"La chèvre qui choisit la liberté, au prix de sa vie"},{"id":"d1","texte":"La fierté d’un monde ancien vaincu par le progrès"},{"id":"d2","texte":"L’amour fatal, qui mène au suicide"},{"id":"d3","texte":"L’amour pur et silencieux"}]}]}$ex$::jsonb,
