  ('f38d4b41-f101-560d-88b6-cf200be8583d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Sous le soleil, de la tristesse","competence":"argumenter","situation":"Sana pense que Daudet n’écrit que pour amuser les enfants. Nolan n’est pas d’accord. Lis leur échange, classe les ingrédients du recueil, puis choisis ta conclusion.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Sana","emoji":"👧","cote":"gauche"},{"nom":"Nolan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sana","texte":"Ce sont des contes pour enfants : tout y est drôle et léger."},{"qui":"Nolan","texte":"Pas du tout : sous l’humour, il y a de la mélancolie. Maître Cornille ne moud plus rien et fait semblant."},{"qui":"Sana","texte":"Et alors ? C’est juste une histoire de meunier."},{"qui":"Nolan","texte":"C’est une Provence qui disparaît : la minoterie à vapeur a ruiné le moulin."}]},{"id":"th","type":"tableau","titre":"Deux arguments","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Sous le charme, une Provence qui disparaît","Le progrès ruine les métiers anciens","?"],["« La Chèvre de M. Seguin » est un apologue","Un petit récit pose une question de morale","Liberté ou sécurité ?"]]}],"questions":[{"enonce":"Touche le mot par lequel Nolan nomme ce qui se cache sous l’humour.","aide":"Un sentiment de tristesse douce, lié au passé qui s’en va.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Cherche, dans le dialogue, le meunier ruiné par le progrès.","type":"choix","options":[{"id":"a","texte":"Blanquette et le loup"},{"id":"b","texte":"Le berger des « Étoiles »"},{"id":"c","texte":"La mule du pape et son coup de pied"},{"id":"d","texte":"Maître Cornille et la minoterie à vapeur"}],"multiple":false},{"enonce":"Range chaque élément : il fait sourire, ou il laisse un fond de tristesse ?","aide":"Demande-toi si la scène amuse ou si elle montre quelque chose qui disparaît.","type":"categories","categories":[{"id":"c0","texte":"Ce qui fait sourire"},{"id":"c1","texte":"Ce qui attriste en dessous"}],"items":[{"id":"i0","texte":"Les traditions perdues et les villages vidés"},{"id":"i1","texte":"Maître Cornille qui feint de moudre du blé"},{"id":"i2","texte":"L’oralité et la légèreté du ton"},{"id":"i3","texte":"Le coup de pied que la mule garde sept ans"},{"id":"i4","texte":"Les moulins ruinés par l’industrie"}]},{"enonce":"Quelle conclusion de dissertation le recueil permet-il d’appuyer ?","aide":"Relis la thèse du premier rang du tableau.","type":"choix","options":[{"id":"a","texte":"Le conte peut cacher une nostalgie sous la légèreté"},{"id":"b","texte":"Le recueil décrit fidèlement la vie de Daudet"},{"id":"c","texte":"Le conte est un genre réservé aux jeunes enfants"},{"id":"d","texte":"Le progrès y est présenté comme un bienfait unanime"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Sous l’humour, Daudet cache de la **mélancolie** : celle d’une Provence qui disparaît."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Maître Cornille**, ruiné par la **minoterie à vapeur**, illustre un monde ancien vaincu par le progrès."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"L’**oralité** et la **mule** amusent ; les **moulins ruinés**, les **traditions perdues** et **Cornille** disent la nostalgie."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le recueil montre que **la légèreté et l’humour masquent une nostalgie constante** : un monde rural menacé par l’industrie."}]$ex$::jsonb),
  ('c0fd943c-2302-5f3f-ae94-c4ffef827b57'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"De la Perse à Paris","competence":"lire-carte","situation":"Deux Persans, Usbek et Rica, quittent Ispahan, voyagent en Europe et écrivent à leurs amis, à leurs eunuques et aux femmes de leur sérail, restées en Perse. Situe leur voyage sur la carte, puis identifie les personnages.","documents":[{"id":"carte","type":"carte","titre":"Le voyage des deux Persans","fond":"monde","cadrage":[-10,25,65,58],"lieux":[{"id":"z1","lon":51.68,"lat":32.65,"nom":"Ispahan","symbole":"point","teinte":"corail"},{"id":"z2","lieu":"paris","nom":"Paris","symbole":"point","teinte":"corail"}],"traits":[{"points":[[51.68,32.65],[2.35,48.86]],"style":"fleche","teinte":"violet"}]},{"id":"pers","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Son rôle"],"lignes":[["Usbek","Le philosophe, sérieux, jaloux et despote chez lui"],["Rica","?"],["Roxane","L’épouse révoltée"],["Le grand eunuque","Le gardien du sérail"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ville d’où partent Usbek et Rica, où le sérail est resté.","aide":"Le sérail reste en Perse, loin du voyage.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville où les deux Persans observent les Français.","aide":"Les deux voyageurs écrivent depuis la capitale du royaume de France.","type":"zone","document":"carte","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » pour Rica ?","aide":"Rica s’oppose à Usbek : il est plus jeune et moins grave.","type":"choix","options":[{"id":"a","texte":"Une épouse du sérail qui se révolte"},{"id":"b","texte":"Un magistrat de Bordeaux qui publie le livre"},{"id":"c","texte":"Le jeune voyageur, moqueur et léger"},{"id":"d","texte":"Un vieux philosophe sérieux et jaloux"}],"multiple":false},{"enonce":"Complète le résumé du dispositif.","aide":"Relis la situation, en haut de l’exercice.","type":"trous","segments":["Deux ",0," voyagent en ",1," et écrivent à leurs amis, à leurs ",2," et aux femmes de leur sérail."],"banque":["Français","Persans","médecins","Europe","Asie","eunuques"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Usbek et Rica quittent **Ispahan** ; leur sérail y est resté."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Les Persans découvrent la France depuis **Paris**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Rica est **jeune, moqueur et léger** : son regard amuse là où celui d’Usbek est plus sérieux."},{"cle":{"type":"trous","trous":[["persans"],["europe"],["eunuques"]]},"affichage":"Persans · Europe · eunuques","explication":"Deux **Persans** voyagent en **Europe** et écrivent à leurs amis, à leurs **eunuques** et aux femmes du sérail."}]$ex$::jsonb),
  ('c0fd943c-2302-5f3f-ae94-c4ffef827b57'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les magiciens de Paris","competence":"analyser-texte","situation":"Lis une lettre de Rica écrite pour l’exercice, puis retrouve ce qu’elle vise et comment l’apologue des Troglodytes continue le raisonnement.","documents":[{"id":"mag","type":"texte","genre":"lettre","titre":"Une lettre de Rica","blocs":["Rica à son ami, de Paris.","Le roi de France est un grand magicien : il fait croire à ses sujets que de simples papiers valent de l’argent. Il y a un autre magicien plus fort encore, le pape : il leur fait croire que trois ne font qu’un. Ces gens ont l’esprit si doux qu’ils croient tout, et personne ne s’en étonne, sauf moi."],"source":"Texte écrit pour l’exercice, à la manière des *Lettres persanes*"},{"id":"tro","type":"tableau","titre":"L’apologue des Troglodytes (lettres XI à XIV)","colonnes":["Peuple","Sort"],"lignes":[["Les Troglodytes égoïstes","?"],["Les Troglodytes vertueux","Ils prospèrent, puis demandent un roi"]]}],"questions":[{"enonce":"Touche le mot par lequel Rica désigne le roi.","aide":"Rica compare le pouvoir du roi à un tour de passe-passe.","type":"zone","document":"mag","multiple":false},{"enonce":"Pourquoi Rica traite-t-il le roi et le pape de « magiciens » ?","aide":"Rica est un étranger : il ne connaît ni les finances ni la théologie du pays.","type":"choix","options":[{"id":"a","texte":"Il décrit sans comprendre : tout lui paraît un tour de magie"},{"id":"b","texte":"Il croit vraiment que le roi et le pape ont des pouvoirs magiques"},{"id":"c","texte":"Il veut flatter le roi pour obtenir une pension de la cour"},{"id":"d","texte":"Il imite le langage des *Mille et Une Nuits* pour distraire ses amis"}],"multiple":false},{"enonce":"Relie chaque cible de la satire à ce qui est moqué.","aide":"Les deux premiers sont dans la lettre ; le troisième, dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Le roi"},{"id":"g1","texte":"Le pape"},{"id":"g2","texte":"Les Troglodytes"}],"droite":[{"id":"d0","texte":"L’idée que le papier vaut de l’argent"},{"id":"d1","texte":"La question des institutions qui rendent la liberté possible"},{"id":"d2","texte":"L’idée que trois ne font qu’un"}]},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Un peuple où chacun ne pense qu’à soi peut-il durer ?","type":"choix","options":[{"id":"a","texte":"Il est sauvé par les eunuques"},{"id":"b","texte":"Il se choisit un roi vertueux"},{"id":"c","texte":"Il s’autodétruit"},{"id":"d","texte":"Il devient le plus riche de la région"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"Pour Rica, le roi est un grand **magicien** : il fait croire des choses qu’il ne comprend pas."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un étranger qui ne comprend pas les **raisons** d’une croyance la décrit comme un **tour de magie** : c’est le regard éloigné."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Rica s’étonne du **papier-monnaie** et de la **Trinité** ; l’apologue pose la question des **institutions** de la liberté."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un peuple égoïste **s’autodétruit** ; un peuple vertueux prospère : l’apologue interroge les institutions de la liberté."}]$ex$::jsonb),
  ('c0fd943c-2302-5f3f-ae94-c4ffef827b57'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un modèle réduit du despotisme","competence":"argumenter","situation":"Camille ne voit dans le sérail qu’un décor exotique. Ethan veut y lire de la politique. Lis leur débat et la lettre de Roxane écrite pour l’exercice, puis tranche.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Ethan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Le sérail, c’est juste un décor oriental pour faire exotique."},{"qui":"Ethan","texte":"Non : c’est un modèle réduit du despotisme : Usbek y règne par la crainte, et tout s’écroule."},{"qui":"Camille","texte":"Mais Usbek est un philosophe de la liberté !"},{"qui":"Ethan","texte":"Justement : ses idées s’arrêtent à la porte de chez lui."}]},{"id":"rox","type":"texte","genre":"lettre","titre":"Une lettre de Roxane","blocs":["Roxane à Usbek.","Tu m’as laissée sous la garde de tes eunuques et tu as cru que la crainte suffisait à tenir un sérail. Elle ne tient qu’un temps. J’ai trahi ta confiance ; j’ai pris le poison. Quand tu liras cette lettre, je serai libre, et je ne t’ai jamais aimé."],"source":"Texte écrit pour l’exercice, à la manière des *Lettres persanes*"}],"questions":[{"enonce":"Touche le mot qui dit ce que le sérail représente en petit.","aide":"Ethan parle d’un pouvoir absolu qui s’exerce par la crainte.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche le mot qui dit sur quoi reposait le pouvoir d’Usbek dans le sérail.","aide":"Roxane dit que cela « ne tient qu’un temps ».","type":"zone","document":"rox","multiple":false},{"enonce":"Range chaque trait : Usbek voyageur, ou Usbek chez lui ?","aide":"Distingue ce qu’il dit dans ses lettres à ses amis et ce qu’il impose dans son sérail.","type":"categories","categories":[{"id":"c0","texte":"Le philosophe voyageur"},{"id":"c1","texte":"Le despote du sérail"}],"items":[{"id":"i0","texte":"Il fait garder ses femmes par des eunuques"},{"id":"i1","texte":"Il se fait obéir par la crainte"},{"id":"i2","texte":"Il s’interroge sur la liberté avec ses amis"},{"id":"i3","texte":"Il observe les usages français depuis Paris"}]},{"enonce":"Quelle conclusion de dissertation le sérail permet-il d’appuyer ?","aide":"Le roman parle de la Perse, mais pense à la monarchie française.","type":"choix","options":[{"id":"a","texte":"Un roman ne peut jamais porter de critique politique"},{"id":"b","texte":"Le despotisme est solide quand il repose sur la crainte"},{"id":"c","texte":"La fiction peut critiquer le pouvoir sans l’attaquer de front"},{"id":"d","texte":"Le sérail est un simple décor sans lien avec la France"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Le sérail est un modèle réduit du **despotisme** : un pouvoir sans lois, qui finit par s’écrouler."},{"cle":{"type":"zone","ids":["m19"]},"explication":"Usbek croyait la **crainte** suffisante pour tenir son sérail : c’est ce qui s’écroule."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **penseur** de la liberté s’interroge et observe ; le **despote** garde ses femmes et règne par la crainte."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le sérail permet de parler du **pouvoir** et de la condition des femmes : la fiction porte une **critique politique** sans danger direct."}]$ex$::jsonb),
  ('9fe9cd1b-9a25-5a09-8d19-926d111d5b19'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une mère, une fille, deux provinces","competence":"se-reperer-temps","situation":"Madame de Sévigné écrit à sa fille, Madame de Grignan, qui part vivre en Provence en 1671, au château de Grignan. Place les lieux et les dates de cette correspondance.","documents":[{"id":"carte","type":"carte","titre":"Entre Paris, les Rochers et Grignan","fond":"france","lieux":[{"id":"z1","lieu":"paris","nom":"Paris","symbole":"point"},{"id":"z2","lon":-1.2,"lat":48.12,"nom":"Les Rochers","symbole":"point"},{"id":"z3","lon":4.9,"lat":44.42,"nom":"Grignan","symbole":"point"}],"traits":[{"points":["paris",[4.9,44.42]],"style":"fleche","teinte":"violet"}]},{"id":"fr","type":"frise","titre":"La vie et les lettres","debut":1620,"fin":1730,"pas":10,"evenements":[{"id":"z4","date":1626,"nom":"Naissance"},{"id":"z5","date":1671,"nom":"Fille partie"},{"id":"z6","date":1696,"nom":"Mort"},{"id":"z7","date":1725,"nom":"Publication"}]}],"questions":[{"enonce":"Touche le lieu où vit Madame de Grignan, loin de sa mère.","aide":"C’est le point au bout de la flèche des lettres.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche l’année où les lettres commencent à être publiées.","aide":"Elles paraissent après la mort de leur autrice.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent la mort de Madame de Sévigné du début de la publication ?","aide":"Soustrais la date de sa mort à celle de la publication.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase.","aide":"Relis la situation : à qui écrit-elle ?","type":"trous","segments":["La plupart des lettres sont adressées à sa ",0,", Madame de ",1,", partie vivre en ",2," en 1671."],"banque":["Grignan","La Fayette","cousine","Bretagne","fille","Provence"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Madame de Grignan vit à **Grignan**, en Provence : c’est là que partent les lettres."},{"cle":{"type":"zone","ids":["z7"]},"explication":"Les lettres sont publiées à partir de **1725**."},{"cle":{"type":"nombre","valeur":29,"tolerance":0},"affichage":"29 ans","explication":"1725 − 1696 = **29 ans** : elle ne pensait pas être publiée."},{"cle":{"type":"trous","trous":[["fille"],["grignan"],["provence"]]},"affichage":"fille · Grignan · Provence","explication":"Elle écrit à sa **fille**, Madame de **Grignan**, partie vivre en **Provence** en 1671."}]$ex$::jsonb),
  ('9fe9cd1b-9a25-5a09-8d19-926d111d5b19'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une nouvelle pour la poste","competence":"analyser-texte","situation":"Lis une lettre écrite pour l’exercice, dans l’esprit de Madame de Sévigné, qui raconte la mort de Vatel. Puis relève les traits de son style.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre à la manière de Madame de Sévigné","blocs":["Ma chère fille, je ne sais par où commencer, tant la nouvelle est affreuse.","Vatel, le maître d’hôtel, attendait la marée pour le grand dîner ; elle n’arrivait pas. Il a perdu la tête et s’est transpercé de son épée. Voyez comme on peut mourir d’un poisson !","Je vous embrasse mille fois, car vous me manquez à chaque ligne."],"source":"Texte écrit pour l’exercice, à la manière de Madame de Sévigné"}],"questions":[{"enonce":"Touche le mot qui dit pourquoi Vatel perd la tête.","aide":"Il attendait un produit de la mer qui n’arrivait pas.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le verbe qui dit la mort de Vatel.","aide":"Il se jette sur son épée.","type":"zone","document":"lettre","multiple":false},{"enonce":"Relie chaque trait de style à son exemple dans la lettre.","aide":"Pour chaque phrase, demande-toi si elle annonce, plaisante ou parle à la fille.","type":"association","gauche":[{"id":"g0","texte":"Une annonce frappante"},{"id":"g1","texte":"Le passage du grave au léger"},{"id":"g2","texte":"Un ton affectueux"}],"droite":[{"id":"d0","texte":"Voyez comme on peut mourir d’un poisson !"},{"id":"d1","texte":"Vous me manquez à chaque ligne"},{"id":"d2","texte":"Je ne sais par où commencer, tant la nouvelle est affreuse"}]},{"enonce":"Pourquoi les lettres de Madame de Sévigné paraissent-elles si vivantes ?","aide":"Elle écrit comme on converse.","type":"choix","options":[{"id":"a","texte":"Elle les écrit toujours dans le même ordre strict"},{"id":"b","texte":"Elle les fait relire par sa fille avant l’envoi"},{"id":"c","texte":"Elle écrit sans se relire et sans penser être publiée"},{"id":"d","texte":"Elle les a retravaillées pour la publication à Paris"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Vatel attend la **marée**, le poisson frais : elle n’arrive pas, et il perd la tête."},{"cle":{"type":"zone","ids":["m38"]},"explication":"Vatel s’est **transpercé** de son épée : la nouvelle est grave, et dite sans détour."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"L’**annonce frappante** ouvre la lettre ; le **grave au léger** vient avec la plaisanterie sur le poisson ; la fin est **affectueuse**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Elle écrit **sans se relire** et **sans imaginer être publiée** : c’est ce qui rend ses lettres si vivantes, comme une conversation."}]$ex$::jsonb),
  ('9fe9cd1b-9a25-5a09-8d19-926d111d5b19'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une lettre peut-elle être une œuvre ?","competence":"argumenter","situation":"Léa pense qu’une lettre privée n’est pas de la littérature. Karim n’est pas d’accord. Lis la phrase célèbre, leur débat, puis le tableau pour construire ta réponse.","documents":[{"id":"cit","type":"texte","genre":"lettre","titre":"Une annonce célèbre","blocs":["Je m’en vais vous mander la chose la plus étonnante, la plus surprenante, la plus merveilleuse, la plus miraculeuse…"],"source":"Madame de Sévigné, lettre à Coulanges, 15 décembre 1670"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👩","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Une lettre privée, ce n’est pas de la littérature : elle l’écrit sans se relire."},{"qui":"Karim","texte":"Au contraire : c’est ce qui rend ses lettres si vivantes. Elle écrit comme on converse."}]},{"id":"th","type":"tableau","titre":"Deux arguments","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Une lettre privée peut devenir une œuvre","Le ton oral donne de la vie à la nouvelle","?"],["La lettre dit le XVIIe siècle par les détails","On y voit la cour de Louis XIV de très près","La mort de Vatel"]]}],"questions":[{"enonce":"Touche les quatre adjectifs qui annoncent la nouvelle.","aide":"Ils se suivent, tous au superlatif.","type":"zone","document":"cit","multiple":true},{"enonce":"Quel effet produit cette accumulation d’adjectifs ?","aide":"On attend la nouvelle, et elle n’arrive pas encore.","type":"choix","options":[{"id":"a","texte":"Elle prépare une réponse polie à une question reçue"},{"id":"b","texte":"Elle décrit en détail un événement déjà connu de tous"},{"id":"c","texte":"Elle retarde l’annonce et attise la curiosité du destinataire"},{"id":"d","texte":"Elle démontre une thèse philosophique par étapes"}],"multiple":false},{"enonce":"Touche le mot par lequel Karim défend la valeur de la spontanéité.","aide":"C’est ce que Léa voit comme un défaut, et Karim comme une qualité.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple, pris dans le premier document, faut-il écrire dans la case « ? » du tableau ?","aide":"La case illustre le « ton oral » : cherche la phrase de la lettre qui parle comme on converse.","type":"choix","options":[{"id":"a","texte":"La santé et le temps qu’il fait aux Rochers"},{"id":"b","texte":"La formule d’annonce « la chose la plus étonnante… »"},{"id":"c","texte":"Le procès de Fouquet suivi de près"},{"id":"d","texte":"Les foins et les paysans des Rochers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m13","m16","m19"]},"explication":"**Étonnante, surprenante, merveilleuse, miraculeuse** : l’accumulation prépare la nouvelle."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’accumulation **retarde l’annonce** et **attise la curiosité** : on lit comme on écoute quelqu’un qui raconte."},{"cle":{"type":"zone","ids":["m26"]},"explication":"L’écriture sans retouche rend les lettres **vivantes** : c’est ce qui les fait entrer en littérature."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’exemple du **ton oral** est la formule d’annonce : « la chose la plus étonnante… », une nouvelle dite comme à voix haute."}]$ex$::jsonb),
  ('518de91f-e5fb-5db6-8a07-14a13815417e'::uuid, 1, 1, 5, 20, 4,
