  ('518de91f-e5fb-5db6-8a07-14a13815417e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un héros qui se perd","competence":"argumenter","situation":"Inès croit que Lorenzo a réussi. Yanis pense le contraire. Lis la célèbre phrase de Lorenzo et leur débat, puis classe ce que la pièce nous dit.","documents":[{"id":"cit","type":"texte","genre":"theatre","titre":"Une phrase de Lorenzo","blocs":[{"personnage":"Lorenzo","replique":"« Le vice a été pour moi un vêtement, maintenant il est collé à ma peau. »"}],"source":"Alfred de Musset, *Lorenzaccio* (1834)"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Lorenzo a réussi : le tyran est mort, mission accomplie."},{"qui":"Yanis","texte":"Il a réussi son crime, pas son projet : rien n’a changé à Florence."},{"qui":"Inès","texte":"Alors il a tué pour rien ?"},{"qui":"Yanis","texte":"Il a surtout perdu ce qu’il était : il joue un rôle jusqu’à s’y perdre."}]}],"questions":[{"enonce":"Touche le mot qui dit que le vice était d’abord un rôle qu’on enfile.","aide":"Un habit qu’on peut ôter, au début.","type":"zone","document":"cit","multiple":false},{"enonce":"Touche le mot qui dit que le rôle est devenu inséparable de Lorenzo.","aide":"Ce qui est collé à… quoi ?","type":"zone","document":"cit","multiple":false},{"enonce":"Que dit cette phrase de Lorenzo sur lui-même ?","aide":"Un vêtement qui ne s’enlève plus n’est plus un déguisement.","type":"choix","options":[{"id":"a","texte":"Il se vante d’avoir trompé tout Florence"},{"id":"b","texte":"Il regrette d’avoir quitté la vie de Venise"},{"id":"c","texte":"Son rôle de débauché est devenu sa vraie nature"},{"id":"d","texte":"Il a changé de costume pour la fête du duc"}],"multiple":false},{"enonce":"Range chaque fait : drame politique ou drame de l’identité ?","aide":"Demande-toi si le fait concerne Florence ou ce que devient Lorenzo.","type":"categories","categories":[{"id":"c0","texte":"Drame politique"},{"id":"c1","texte":"Drame de l’identité"}],"items":[{"id":"i0","texte":"Il joue un rôle jusqu’à s’y perdre"},{"id":"i1","texte":"Les républicains ne se soulèvent pas"},{"id":"i2","texte":"Le vice est collé à sa peau"},{"id":"i3","texte":"Un nouveau duc est installé aussitôt"}]},{"enonce":"Quelle conclusion de dissertation sur l’action politique la pièce permet-elle d’appuyer ?","aide":"Relis la réplique de Yanis : rien n’a changé à Florence.","type":"choix","options":[{"id":"a","texte":"Un seul acte courageux suffit à renverser un régime"},{"id":"b","texte":"Un acte individuel ne suffit pas à changer l’Histoire"},{"id":"c","texte":"Les républicains sont les vrais héros de la pièce"},{"id":"d","texte":"L’action politique n’a de sens que dans la débauche"}],"multiple":false}]}$ex$::jsonb,
