   $ex${"titre":"Un dimanche à Yonville","competence":"analyser-texte","situation":"Lis une courte scène écrite pour l’exercice, puis suis l’engrenage qui conduit Emma à sa perte.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"La place d’Yonville","blocs":["Le dimanche, à Yonville, rien ne bougeait. Emma, derrière sa fenêtre, voyait passer le percepteur Binet, qui tournait ses ronds de serviette en sifflant.","Elle pensait aux bals des romans qu’elle avait lus au couvent, et la place lui paraissait plus vide encore."],"source":"Texte écrit pour l’exercice, à la manière de Flaubert"},{"id":"fil","type":"chaine","titre":"L’engrenage","disposition":"colonne","noeuds":[{"id":"z1","texte":"Emma rêve de la vie des romans"},{"id":"z2","texte":"Elle emprunte à Lheureux et s’endette"},{"id":"z3","texte":"Menacée de saisie, elle est abandonnée"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Charles découvre les lettres et meurt"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le mot qui désigne l’occupation absurde de Binet.","aide":"Ce qu’il tourne, en sifflant, pour passer le temps.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche l’adjectif qui dit l’effet des romans sur sa vision de la place.","aide":"Comparée aux bals des romans, la place paraît… ?","type":"zone","document":"scene","multiple":false},{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Elle obtient du poison par Justin, l’apprenti du pharmacien.","type":"choix","options":[{"id":"a","texte":"Elle rembourse Lheureux grâce à Léon"},{"id":"b","texte":"Elle s’enfuit avec Rodolphe à l’étranger"},{"id":"c","texte":"Elle avale de l’arsenic et meurt"},{"id":"d","texte":"Elle est sauvée par Homais, qui la soigne"}],"multiple":false},{"enonce":"Relie chaque personnage secondaire à son rôle.","aide":"Chacun apparaît à un moment de l’engrenage ou de la fin.","type":"association","gauche":[{"id":"g0","texte":"Binet"},{"id":"g1","texte":"Bournisien"},{"id":"g2","texte":"Justin"},{"id":"g3","texte":"Berthe"}],"droite":[{"id":"d0","texte":"Le curé incapable de comprendre Emma"},{"id":"d1","texte":"L’apprenti du pharmacien, par qui Emma obtient l’arsenic"},{"id":"d2","texte":"Le percepteur aux ronds de serviette"},{"id":"d3","texte":"Sa fille, négligée puis placée en filature"}]},{"enonce":"Pourquoi Flaubert donne-t-il à Binet ce geste répété, sans commentaire ?","aide":"L’ironie de Flaubert ne commente pas : elle montre.","type":"choix","options":[{"id":"a","texte":"Pour annoncer la mort prochaine de Binet"},{"id":"b","texte":"Pour distraire le lecteur de l’histoire d’Emma"},{"id":"c","texte":"Pour condamner clairement les petits fonctionnaires"},{"id":"d","texte":"Pour incarner l’ennui, sans que le narrateur juge"}],"multiple":false}]}$ex$::jsonb,
