  ('a9c0c8dd-ca06-56f0-8447-c6b530d1ef2e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à Graciosa","competence":"analyser-texte","situation":"Lis une lettre de Madeleine écrite pour l’exercice, puis remets dans l’ordre les grands moments du roman.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre de Madeleine","blocs":["Chère Graciosa,","Tu ne devineras jamais ce que j’ai fait : je suis devenue homme pour quelque temps. Sous le nom de Théodore, je vais dans le monde, j’observe les hommes quand ils se croient entre eux, avant de choisir un amant. Si tu me vois dans un salon, ne me reconnais pas !"],"source":"Texte écrit pour l’exercice, à la manière de Gautier"}],"questions":[{"enonce":"Touche le mot qui dit en quoi Madeleine se déguise.","aide":"Elle prend un nom masculin : Théodore.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le verbe qui dit ce qu’elle fait des hommes.","aide":"Elle les regarde sans être reconnue.","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi Madeleine se déguise-t-elle ?","aide":"Relis la fin de la phrase : avant de… quoi ?","type":"choix","options":[{"id":"a","texte":"Pour observer les hommes entre eux avant de choisir un amant"},{"id":"b","texte":"Pour prendre part à des duels réservés aux hommes"},{"id":"c","texte":"Pour fuir un mariage arrangé que sa famille lui impose"},{"id":"d","texte":"Pour devenir comédienne dans une troupe de Shakespeare"}],"multiple":false},{"enonce":"Remets dans l’ordre les grands moments du roman.","aide":"Le déguisement vient d’abord, la disparition en dernier.","type":"ordre","items":[{"id":"a","texte":"Elle disparaît"},{"id":"b","texte":"Elle se donne ensuite à Rosette, la maîtresse de d’Albert"},{"id":"c","texte":"Madeleine se déguise en Théodore de Sérannes"},{"id":"d","texte":"Une représentation de *Comme il vous plaira* met chacun face à ses désirs"},{"id":"e","texte":"Madeleine se donne à d’Albert"}]}]}$ex$::jsonb,
