   $ex${"titre":"Ce que fait l’empereur de son empire","competence":"analyser-texte","situation":"Lis un résumé écrit pour l’exercice, puis retrouve les actes d’Hadrien et sa fin.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"L’empereur à sa table","blocs":["Un vieil empereur, malade, prend la plume pour écrire à son petit-fils adoptif, Marc Aurèle. Il ne reprend pas les conquêtes de son prédécesseur Trajan : il consolide les frontières, jusqu’au mur de Bretagne. Il restaure Athènes, fait bâtir la Villa Adriana et le Panthéon. Un jour, le jeune Antinoüs, qu’il aime, se noie dans le Nil."],"source":"Résumé écrit pour l’exercice, d’après *Mémoires d’Hadrien* de Marguerite Yourcenar"},{"id":"vie","type":"tableau","titre":"Étapes de la vie d’Hadrien","colonnes":["Étape","Ce qu’elle apporte"],"lignes":[["Sa politique","Il arrête l’expansion militaire et consolide les frontières"],["Antinoüs","Jeune Bithynien noyé dans le Nil en 130"],["La fin","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui disent ce qu’Hadrien fait de ses frontières, au lieu de conquérir.","aide":"Cherche un verbe et son complément.","type":"zone","document":"resume","multiple":true},{"enonce":"Relie chaque réalisation ou épisode au lieu qu’il évoque.","aide":"Chaque épisode du résumé a son lieu.","type":"association","gauche":[{"id":"g0","texte":"Le mur"},{"id":"g1","texte":"La restauration"},{"id":"g2","texte":"La noyade d’Antinoüs"}],"droite":[{"id":"d0","texte":"Le Nil"},{"id":"d1","texte":"Athènes"},{"id":"d2","texte":"La Bretagne"}]},{"enonce":"Que faut-il écrire dans la case « ? » de la ligne « La fin » ?","aide":"Le cours dit qu’il accepte la mort.","type":"choix","options":[{"id":"a","texte":"Un retour triomphal à Rome, couronné par le Sénat et le peuple"},{"id":"b","texte":"La révolte juive, la maladie, la succession — et l’acceptation de la mort"},{"id":"c","texte":"Une nouvelle campagne militaire qui étend l’empire vers l’est"},{"id":"d","texte":"L’abdication d’Hadrien, qui part vivre en Grèce avec Antinoüs"}],"multiple":false},{"enonce":"Complète ce que dit le tableau sur Antinoüs.","aide":"La ligne « Antinoüs » donne les trois réponses.","type":"trous","segments":["Antinoüs, jeune ",0,", est noyé dans le ",1," en ",2,"."],"banque":["130","Nil","Bithynien","Tibre","Grec"]}]}$ex$::jsonb,
