   $ex${"titre":"Dire « je » à la place d’un autre","competence":"argumenter","situation":"Deux élèves débattent du genre du livre. Lis leur échange et un court passage écrit pour l’exercice, à la manière de Yourcenar.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Noé","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"C’est un roman historique : l’auteur raconte la vie d’Hadrien de l’extérieur."},{"qui":"Noé","texte":"Non : c’est Hadrien qui dit « je », dans une lettre. Elle écrit à la première personne la voix d’un autre."},{"qui":"Emma","texte":"Alors ce n’est pas seulement de l’histoire ?"},{"qui":"Noé","texte":"C’est une méditation sur le pouvoir, le corps, l’art et la mort."}]},{"id":"passage","type":"texte","genre":"recit","titre":"Un passage à la manière de Yourcenar","blocs":["J’ai longtemps cru que le pouvoir consistait à avancer. Je sais à présent qu’il consiste parfois à s’arrêter : tenir une frontière coûte moins de vies que la franchir. Chaque matin, je compte les jours qui me restent comme on compte les pierres d’un mur."],"source":"Texte écrit pour l’exercice, à la manière de Marguerite Yourcenar"}],"questions":[{"enonce":"Touche les deux verbes que le narrateur oppose pour définir le pouvoir.","aide":"L’un est ce qu’il croyait, l’autre ce qu’il sait.","type":"zone","document":"passage","multiple":true},{"enonce":"Quelle idée du cours la réplique de Noé résume-t-elle ?","aide":"Qui dit « je » dans le livre ?","type":"choix","options":[{"id":"a","texte":"Un récit d’aventures écrit à la troisième personne"},{"id":"b","texte":"Le journal intime d’une romancière sur son époque"},{"id":"c","texte":"Un traité d’histoire fondé sur des archives"},{"id":"d","texte":"L’écriture à la première personne d’un autre"}],"multiple":false},{"enonce":"Range chaque élément : ce qu’Hadrien fait de l’empire, ou ce qu’il subit ?","aide":"Un trait relève de sa décision, l’autre de ce qui lui arrive.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’il fait"},{"id":"c1","texte":"Ce qu’il subit"}],"items":[{"id":"i0","texte":"La mort d’Antinoüs"},{"id":"i1","texte":"Arrêter l’expansion militaire"},{"id":"i2","texte":"La maladie"},{"id":"i3","texte":"Consolider les frontières"},{"id":"i4","texte":"Restaurer Athènes"}]},{"enonce":"Relie chaque élément du livre à ce qu’il apporte.","aide":"Chaque élément concerne la fabrication du livre.","type":"association","gauche":[{"id":"g0","texte":"Les *Carnets de notes*"},{"id":"g1","texte":"Les titres latins des six sections"},{"id":"g2","texte":"La forme de la lettre"}],"droite":[{"id":"d0","texte":"Elle donne la parole à Hadrien, qui dit « je »"},{"id":"d1","texte":"Ils placent le livre dans la langue de Rome"},{"id":"d2","texte":"Ils exposent la méthode : érudition d’un côté, magie de l’autre"}]}]}$ex$::jsonb,
